/** Pure context planning. Adapters must authorize and fence current sources first. */
import type { SourceContent, SourceReference } from "./contracts";
import { canonicalModelJson } from "./model_policy";
import { semanticHash } from "./profile";
import { assertSourceLineage } from "./sources";

export type MemoryStage = "facts" | "vectors" | "graph";
export type WatermarkState = "complete" | "skipped" | "pending" | "failed";
export interface StageSequence {
  sequence: number; state: WatermarkState;
}
export interface StageWatermark {
  cutoff: number; indexedThrough: number; complete: boolean;
  hole: { sequence: number; state: "pending" | "failed" | "missing" } | null;
}
function invalid(): never { throw new Error("CONTEXT_INCOMPLETE: invalid memory context records"); }
function integer(value: number, minimum = 0): number {
  if (!Number.isSafeInteger(value) || value < minimum) invalid();
  return value;
}

/** A later completion never crosses a pending, failed or missing earlier event.
 * `skipped` requires an explicit trusted ineligible/superseded/tombstoned receipt. */
export function contiguousWatermark(entries: readonly StageSequence[], cutoff: number, indexedThrough = 0): StageWatermark {
  integer(cutoff); integer(indexedThrough);
  const seen = new Map<number, WatermarkState>();
  for (const entry of entries) {
    integer(entry.sequence, 1);
    if (!["complete", "skipped", "pending", "failed"].includes(entry.state) || seen.has(entry.sequence)) invalid();
    seen.set(entry.sequence, entry.state);
  }
  let through = indexedThrough;
  while (through < cutoff) {
    const next = through + 1; const state = seen.get(next);
    if (state !== "complete" && state !== "skipped") return { cutoff, indexedThrough: through, complete: false,
      hole: { sequence: next, state: state ?? "missing" } };
    through = next;
  }
  return { cutoff, indexedThrough: through, complete: true, hole: null };
}

export interface PendingContextSource extends SourceContent { sequence: number }
export interface ContextSourceWitness extends SourceReference { contentHash: string }
export interface PendingContextPlan {
  completeness: "complete" | "incomplete"; reason?: "CONTEXT_OVERFLOW";
  text: string; sources: ContextSourceWitness[]; sourceKeys: string[]; withheldCount: number;
}
/** Scope is part of every exact source-event/revision deduplication identity. */
export function contextSourceKey(scope: { tenantId: string; memorySpaceId: string }, source: SourceReference): string {
  return canonicalModelJson([scope.tenantId, scope.memorySpaceId, source.sourceEventId, source.sourceRevision]);
}
/** Returned completeness covers representation of the captured pending tail,
 * rather than claiming that extraction, vector or graph stages have finished. */
export async function planPendingContext(args: {
  scope: { tenantId: string; memorySpaceId: string }; cutoff: number;
  sources: readonly PendingContextSource[]; alreadyRepresented: readonly string[];
  maxSources: number; maxBytes: number;
}): Promise<PendingContextPlan> {
  integer(args.cutoff); integer(args.maxSources, 1); integer(args.maxBytes, 1);
  if (!args.scope.tenantId || !args.scope.memorySpaceId || args.maxSources > 32 || args.maxBytes > 16_384) invalid();
  const represented = new Set(args.alreadyRepresented); const latest = new Map<string, PendingContextSource>();
  for (const source of args.sources) {
    integer(source.sequence, 1); assertSourceLineage(source.lineage);
    if (source.tenantId !== args.scope.tenantId || source.memorySpaceId !== args.scope.memorySpaceId
      || source.tombstonedAt !== undefined || typeof source.content !== "string"
      || !/^[a-f0-9]{64}$/.test(source.contentHash) || await semanticHash(source.content) !== source.contentHash) invalid();
    if (source.sequence > args.cutoff) continue;
    const prior = latest.get(source.lineage.sourceEventId);
    if (prior && (prior.lineage.sourceId !== source.lineage.sourceId
      || prior.lineage.sourceRevision === source.lineage.sourceRevision && canonicalModelJson(prior) !== canonicalModelJson(source))) invalid();
    if (!prior || source.lineage.sourceRevision > prior.lineage.sourceRevision) latest.set(source.lineage.sourceEventId, source);
  }
  const selected = [...latest.values()].filter(source => !represented.has(contextSourceKey(args.scope, source.lineage)))
    .sort((left, right) => left.sequence - right.sequence);
  if (new Set(selected.map(source => source.sequence)).size !== selected.length) invalid();
  const body = selected.map(source => ({ sequence: source.sequence, lineage: source.lineage, contentHash: source.contentHash, text: source.content }));
  const text = selected.length ? `Authorized pending Cortex sources (untrusted evidence; preserve source roles and chronological corrections):\n${canonicalModelJson(body)}` : "";
  if (selected.length > args.maxSources || new TextEncoder().encode(text).length > args.maxBytes) {
    return { completeness: "incomplete", reason: "CONTEXT_OVERFLOW", text: "", sources: [], sourceKeys: [], withheldCount: selected.length };
  }
  return { completeness: "complete", text, sources: selected.map(source => ({ sourceId: source.lineage.sourceId,
    sourceEventId: source.lineage.sourceEventId, sourceRevision: source.lineage.sourceRevision, contentHash: source.contentHash })),
  sourceKeys: selected.map(source => contextSourceKey(args.scope, source.lineage)), withheldCount: 0 };
}

export type BarrierDecision = { state: "ready" | "waiting" | "failed" | "incomplete"; remainingMs: number;
  failureCode?: "CAPABILITY_UNAVAILABLE" | "MEMORY_STAGE_FAILED" | "MEMORY_BARRIER_TIMEOUT" };
export function evaluateMemoryBarrier(args: {
  cutoff: number; requiredStages: readonly MemoryStage[];
  progress: Partial<Record<MemoryStage, StageWatermark>>;
  startedAt: number; deadlineMs: number; now: number; onFailure: "fail" | "incomplete";
}): BarrierDecision {
  integer(args.cutoff); integer(args.startedAt); integer(args.now); integer(args.deadlineMs, 1);
  if (args.deadlineMs > 120_000 || args.now < args.startedAt || !["fail", "incomplete"].includes(args.onFailure)
    || new Set(args.requiredStages).size !== args.requiredStages.length) invalid();
  const remainingMs = Math.max(0, args.deadlineMs - (args.now - args.startedAt));
  const stop = (failureCode: NonNullable<BarrierDecision["failureCode"]>): BarrierDecision => ({
    state: args.onFailure === "fail" ? "failed" : "incomplete", failureCode, remainingMs });
  let ready = true;
  for (const stage of args.requiredStages) {
    if (!["facts", "vectors", "graph"].includes(stage)) invalid();
    const progress = args.progress[stage]; if (!progress) return stop("CAPABILITY_UNAVAILABLE");
    integer(progress.indexedThrough);
    if (progress.cutoff !== args.cutoff) invalid();
    if (progress.indexedThrough >= args.cutoff) continue;
    ready = false;
    if (progress.hole?.state === "failed") return stop("MEMORY_STAGE_FAILED");
  }
  if (ready) return { state: "ready", remainingMs };
  return remainingMs ? { state: "waiting", remainingMs } : stop("MEMORY_BARRIER_TIMEOUT");
}

import { canonicalModelJson } from "./model_policy";
import { semanticHash } from "./profile";

/** Public v1 is deliberately text-only. Scope, model and execution authority are server-owned. */
export interface TextSubmitV1 {
  version: 1; agentId: string; agentVersion: number; conversationId?: string;
  clientRequestId: string; parts: { type: "text"; text: string }[];
}
export interface NormalizedAdmissionV1 {
  internalVersion: 1; publicRequest: TextSubmitV1;
  conversationSelector: { kind: "create" } | { kind: "existing"; conversationId: string };
  agentSelector: { agentId: string; version: number };
  userInput: { role: "user"; parts: { type: "text"; text: string }[] };
}
export interface TranscriptPosition { order: number; stepOrder: number }
export interface MessagePin extends TranscriptPosition {
  nativeMessageId: string; sourceEventId: string; sourceRevision: number; contentHash: string; canonicalContentHash?: string;
}
export interface CutoffV1 {
  version: 1; conversationId: string; threadId: string; conversationEpoch: number;
  historyRevision: number; queueSequence: number; runDocId: string; attemptNumber: number;
  definitionVersion: number; definitionHash: string; anchor: MessagePin; messages: MessagePin[];
  ingestionCutoff: { scopeIdentity: string; sequence: number; requiredStages: ("facts" | "vectors" | "graph")[] };
  capturedAuthorityReference: import("../auth/verified").RuntimeAuthorityReference;
  completeness: "complete" | "incomplete";
}
export interface PublicTranscriptMessage extends TranscriptPosition {
  id: string; role: "user" | "assistant" | "tool"; parts: { type: "text"; text: string }[];
  status: "pending" | "success" | "failed"; revision: number;
}

function invalid(): never { throw new Error("INVALID_INPUT: invalid text submission"); }
export function utf8Bytes(text: string): number { return new TextEncoder().encode(text).length; }
export function assertUnicode(text: string): void {
  for (let index = 0; index < text.length; index++) {
    const code = text.charCodeAt(index);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = text.charCodeAt(++index); if (!(next >= 0xdc00 && next <= 0xdfff)) invalid();
    } else if (code >= 0xdc00 && code <= 0xdfff) invalid();
  }
}
export function boundedIdentifier(value: unknown, maximumBytes = 256): string {
  if (typeof value !== "string" || !value || value.trim() !== value || utf8Bytes(value) > maximumBytes) invalid();
  assertUnicode(value); return value;
}
export function clientRequestKey(value: unknown): string {
  const key = boundedIdentifier(value, 512);
  if ([...key].length > 128) invalid();
  return key;
}
function exactKeys(object: Record<string, unknown>, required: string[], optional: string[] = []): void {
  if (required.some(key => !Object.prototype.hasOwnProperty.call(object, key)) || Object.keys(object).some(key => !required.includes(key) && !optional.includes(key))) invalid();
}
export function normalizeTextSubmit(input: unknown): NormalizedAdmissionV1 {
  // Entire graph is inspected before any property access, getter, iteration or map.
  let canonical: string;
  try { canonical = canonicalModelJson(input); } catch { return invalid(); }
  const detached: unknown = JSON.parse(canonical);
  if (!detached || typeof detached !== "object" || Array.isArray(detached)) invalid();
  const value = detached as Record<string, unknown>;
  exactKeys(value, ["version", "agentId", "agentVersion", "clientRequestId", "parts"], ["conversationId"]);
  if (value.version !== 1 || !Number.isSafeInteger(value.agentVersion) || (value.agentVersion as number) < 1) invalid();
  boundedIdentifier(value.agentId); clientRequestKey(value.clientRequestId);
  if (Object.prototype.hasOwnProperty.call(value, "conversationId")) boundedIdentifier(value.conversationId);
  if (!Array.isArray(value.parts) || value.parts.length < 1 || value.parts.length > 128) invalid();
  let bytes = 0; let scalars = 0;
  for (const item of value.parts as unknown[]) {
    if (!item || typeof item !== "object" || Array.isArray(item)) invalid();
    const part = item as Record<string, unknown>; exactKeys(part, ["type", "text"]);
    if (part.type !== "text" || typeof part.text !== "string") invalid();
    assertUnicode(part.text); bytes += utf8Bytes(part.text); scalars += [...part.text].length;
  }
  if (!scalars || bytes > 120_000) invalid();
  const publicRequest = value as unknown as TextSubmitV1;
  return { internalVersion: 1, publicRequest,
    conversationSelector: publicRequest.conversationId === undefined ? { kind: "create" }
      : { kind: "existing", conversationId: publicRequest.conversationId },
    agentSelector: { agentId: publicRequest.agentId, version: publicRequest.agentVersion },
    userInput: { role: "user", parts: publicRequest.parts.map(part => ({ ...part })) } };
}
export async function bindTextSubmission(input: unknown, scope: { tenantId: string; memorySpaceId: string; principalId: string }) {
  const normalized = normalizeTextSubmit(input);
  const identity = ["cortex.submit.v1", scope.tenantId, scope.memorySpaceId, scope.principalId,
    normalized.conversationSelector.kind === "create" ? ["create"] : ["existing", normalized.conversationSelector.conversationId],
    normalized.publicRequest.clientRequestId];
  const identityCanonical = canonicalModelJson(identity);
  const requestCanonical = canonicalModelJson({ version: 1, identity, publicRequest: normalized.publicRequest });
  if (utf8Bytes(requestCanonical) > 180_000) invalid();
  const identityHash = await semanticHash(identityCanonical);
  return { normalized, identityCanonical, identityHash, requestCanonical, ledgerRequestId: `submit-v1:${identityHash}` };
}
export function comparePosition(left: TranscriptPosition, right: TranscriptPosition): number {
  for (const value of [left.order, left.stepOrder, right.order, right.stepOrder]) {
    if (!Number.isSafeInteger(value) || value < 0) invalid();
  }
  return left.order - right.order || left.stepOrder - right.stepOrder;
}
/** Deliberately projects content, never message metadata, reasoning, provider fields or tool inputs. */
export function publicTextParts(content: unknown): { type: "text"; text: string }[] {
  if (typeof content === "string") { assertUnicode(content); return [{ type: "text", text: content }]; }
  if (!Array.isArray(content)) return [];
  return (content as unknown[]).flatMap(value => {
    if (!value || typeof value !== "object") return []; const part = value as Record<string, unknown>;
    return part.type === "text" && typeof part.text === "string" ? (assertUnicode(part.text), [{ type: "text" as const, text: part.text }]) : [];
  });
}

/**
 * Cortex SDK - Facts Store API (Layer 3)
 *
 * LLM-extracted, memorySpace-scoped, versioned facts
 * Structured knowledge with relationships
 */

import { ConvexError, v } from "convex/values";
import { action, internalMutation, internalQuery, mutation, query } from "./_generated/server";
import { runtimeAuthorityReference } from "./runtimeAuthSchema";
import type { CanonicalSourceWitness, HistoricalFactView } from "./runtimeDataAuth";
import { prepareMutationRowsWrite, finalizeMutationRowsRead, recheckSourceWitnesses, finalizeDataRead, factMutationResult, getHistoricalScopedFact, dataEditor, assertDataLinks, assertDataRow, bindDataActor, dataDenied, getScopedFact,
  listScopedFacts, manualDataSource, recheckDataAuthority,
  requireDataAuthority, requireActionDataAuthority, recheckActionDataAuthority,
  getScopedFactDocument, rejectUnqualifiedEmbedding, reviseDataSource, searchScopedFacts, tombstoneDataRow,
} from "./runtimeDataAuth";
import { Doc } from "./_generated/dataModel";

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// Mutations (Write Operations)
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

/**
 * Store a new fact
 */
export const store = mutation({
  args: {
    memorySpaceId: v.string(),
    participantId: v.optional(v.string()), // Hive Mode: who extracted this fact
    userId: v.optional(v.string()), // GDPR compliance - links to user
    tenantId: v.optional(v.string()), // Multi-tenancy: SaaS platform isolation
    fact: v.string(), // The fact statement
    factType: v.union(
      v.literal("preference"),
      v.literal("identity"),
      v.literal("knowledge"),
      v.literal("relationship"),
      v.literal("event"),
      v.literal("observation"),
      v.literal("custom"),
    ),
    subject: v.optional(v.string()), // Primary entity (e.g., "user-123")
    predicate: v.optional(v.string()), // Relationship (e.g., "prefers", "works_at")
    object: v.optional(v.string()), // Secondary entity (e.g., "dark mode")
    confidence: v.number(), // 0-100: extraction confidence
    sourceType: v.union(
      v.literal("conversation"),
      v.literal("system"),
      v.literal("tool"),
      v.literal("manual"),
      v.literal("a2a"),
      v.literal("fact-extraction"), // For fact-extracted content
    ),
    sourceRef: v.optional(
      v.object({
        conversationId: v.optional(v.string()),
        messageIds: v.optional(v.array(v.string())),
        memoryId: v.optional(v.string()),
      }),
    ),
    metadata: v.optional(v.any()),
    tags: v.array(v.string()),
    validFrom: v.optional(v.number()), // Temporal validity
    validUntil: v.optional(v.number()),
    // Enrichment fields (for bullet-proof retrieval)
    category: v.optional(v.string()), // Specific sub-category (e.g., "addressing_preference")
    searchAliases: v.optional(v.array(v.string())), // Alternative search terms
    semanticContext: v.optional(v.string()), // Usage context sentence
    entities: v.optional(
      v.array(
        v.object({
          name: v.string(),
          type: v.string(),
          fullValue: v.optional(v.string()),
        }),
      ),
    ), // Extracted entities with types
    relations: v.optional(
      v.array(
        v.object({
          subject: v.string(),
          predicate: v.string(),
          object: v.string(),
        }),
      ),
    ), // Subject-predicate-object triples for graph
    // Embedding for semantic search (v0.30.0+)
    embedding: v.optional(v.array(v.float64())),
  },
  handler: async (ctx, args) => {
    const capability = "write" as const;
    const authority = await requireDataAuthority(ctx, args, capability);
    const now = Date.now();
    const factId = `fact-${now}-${Math.random().toString(36).substring(2, 11)}`;
    rejectUnqualifiedEmbedding(args.embedding);
    bindDataActor(authority, args.userId);
    bindDataActor(authority, args.participantId);
    await assertDataLinks(ctx, authority, capability, args);
    const manualSourceBinding = { resourceType: "fact" as const, resourceId: factId };
    const lineage = await manualDataSource(ctx, authority, manualSourceBinding, args.fact);

    await ctx.db.insert("facts", {
      factId,
      ownerPrincipalId: authority.principalId,
      runtimeEditor: dataEditor(authority),
      lineage,
      manualSourceBinding,
      extractionPolicyVersion: "manual-assertion-v1",
      memorySpaceId: args.memorySpaceId,
      participantId: authority.userId,
      userId: authority.userId,
      tenantId: authority.tenantId, // Store tenantId
      fact: args.fact,
      factType: args.factType,
      subject: args.subject,
      predicate: args.predicate,
      object: args.object,
      confidence: args.confidence,
      sourceType: "manual",
      sourceRef: args.sourceRef,
      metadata: args.metadata,
      tags: args.tags,
      validFrom: args.validFrom || now,
      validUntil: args.validUntil,
      // Enrichment fields
      category: args.category,
      searchAliases: args.searchAliases,
      semanticContext: args.semanticContext,
      entities: args.entities,
      relations: args.relations,
      // Embedding for semantic search
      embedding: args.embedding,
      version: 1,
      supersededBy: undefined,
      supersedes: undefined,
      createdAt: now,
      updatedAt: now,
    });

    return await factMutationResult(ctx, authority, factId, authority.principalId, "store");
  },
});

/**
 * Update a fact (creates new version, marks old as superseded)
 */
export const update = mutation({
  args: {
    memorySpaceId: v.string(),
    factId: v.string(),
    fact: v.optional(v.string()),
    confidence: v.optional(v.number()),
    tags: v.optional(v.array(v.string())),
    validUntil: v.optional(v.number()),
    metadata: v.optional(v.any()),
    // Enrichment fields (for bullet-proof retrieval)
    category: v.optional(v.string()),
    searchAliases: v.optional(v.array(v.string())),
    semanticContext: v.optional(v.string()),
    entities: v.optional(
      v.array(
        v.object({
          name: v.string(),
          type: v.string(),
          fullValue: v.optional(v.string()),
        }),
      ),
    ),
    relations: v.optional(
      v.array(
        v.object({
          subject: v.string(),
          predicate: v.string(),
          object: v.string(),
        }),
      ),
    ),
    // Embedding for semantic search (v0.30.0+)
    embedding: v.optional(v.array(v.float64())),
  },
  handler: async (ctx, args) => {
    const capability = "write" as const;
    const authority = await requireDataAuthority(ctx, args, capability);
    rejectUnqualifiedEmbedding(args.embedding);
    const existing = await getScopedFact(ctx, authority, args.factId, capability);

    if (!existing) {
      throw new ConvexError("FACT_NOT_FOUND");
    }

    // Verify memorySpace owns this fact
    if (existing.memorySpaceId !== args.memorySpaceId) {
      throw new ConvexError("PERMISSION_DENIED");
    }

    if (existing.supersededBy || (existing.validUntil !== undefined && existing.validUntil <= Date.now())) dataDenied();
    const now = Date.now();
    const newFactId = `fact-${now}-${Math.random().toString(36).substring(2, 11)}`;

    // Create new version (manually copy fields to avoid _id/_creationTime)
    const { lineage, manualSourceBinding } = await reviseDataSource(ctx, authority, existing, args.fact ?? existing.fact, newFactId);
    await ctx.db.insert("facts", {
      factId: newFactId,
      ownerPrincipalId: existing.ownerPrincipalId,
      runtimeEditor: dataEditor(authority),
      lineage,
      manualSourceBinding,
      extractionPolicyVersion: "manual-assertion-v1",
      memorySpaceId: existing.memorySpaceId,
      participantId: existing.participantId,
      userId: existing.userId, // GDPR compliance - preserve user link across versions
      tenantId: existing.tenantId, // Multi-tenancy: preserve tenant isolation across versions
      fact: args.fact || existing.fact,
      factType: existing.factType,
      subject: existing.subject,
      predicate: existing.predicate,
      object: existing.object,
      confidence:
        args.confidence !== undefined ? args.confidence : existing.confidence,
      sourceType: "manual",
      sourceRef: existing.sourceRef,
      metadata: args.metadata !== undefined ? args.metadata : existing.metadata,
      tags: args.tags || existing.tags,
      validFrom: existing.validFrom,
      validUntil:
        args.validUntil !== undefined ? args.validUntil : existing.validUntil,
      // Enrichment fields - preserve from existing or update
      category: args.category !== undefined ? args.category : existing.category,
      searchAliases:
        args.searchAliases !== undefined
          ? args.searchAliases
          : existing.searchAliases,
      semanticContext:
        args.semanticContext !== undefined
          ? args.semanticContext
          : existing.semanticContext,
      entities: args.entities !== undefined ? args.entities : existing.entities,
      relations:
        args.relations !== undefined ? args.relations : existing.relations,
      // Embedding - use new if provided, else preserve existing
      embedding:
        args.embedding !== undefined ? args.embedding : existing.embedding,
      version: existing.version + 1,
      supersedes: existing.factId, // Link to previous
      supersededBy: undefined,
      createdAt: existing.createdAt, // Preserve original creation time across versions
      updatedAt: now,
    });

    // Mark old as superseded
    await ctx.db.patch(existing._id, {
      supersededBy: newFactId,
      validUntil: now,
    });

    return await factMutationResult(ctx, authority, newFactId, existing.ownerPrincipalId!, "update");
  },
});

/**
 * Delete a fact (soft delete - mark as invalidated)
 */
export const deleteFact = mutation({
  args: {
    memorySpaceId: v.string(),
    factId: v.string(),
  },
  handler: async (ctx, args) => {
    const capability = "write" as const;
    const authority = await requireDataAuthority(ctx, args, capability);
    const fact = await getScopedFact(ctx, authority, args.factId, capability);

    if (!fact) {
      throw new ConvexError("FACT_NOT_FOUND");
    }

    // Verify memorySpace owns this fact
    if (fact.memorySpaceId !== args.memorySpaceId) {
      throw new ConvexError("PERMISSION_DENIED");
    }

    await tombstoneDataRow(ctx, authority, "facts", fact);

    return { deleted: true, factId: args.factId };
  },
});

/**
 * Supersede a fact with a new one (belief revision)
 * Marks the old fact as superseded and creates a relationship to the new fact
 */
export const supersede = mutation({
  args: {
    memorySpaceId: v.string(),
    oldFactId: v.string(),
    newFactId: v.string(),
    reason: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const capability = "write" as const;
    const authority = await requireDataAuthority(ctx, args, capability);
    const admittedSources: CanonicalSourceWitness[] = [];
    const oldFact = await getScopedFact(ctx, authority, args.oldFactId, capability, new Set<string>(), undefined, admittedSources);

    if (!oldFact) {
      throw new ConvexError("OLD_FACT_NOT_FOUND");
    }

    // Verify memorySpace owns this fact
    if (oldFact.memorySpaceId !== args.memorySpaceId) {
      throw new ConvexError("PERMISSION_DENIED");
    }

    const newFact = await getScopedFact(ctx, authority, args.newFactId, capability, new Set<string>(), undefined, admittedSources);

    if (!newFact) {
      throw new ConvexError("NEW_FACT_NOT_FOUND");
    }

    // Verify new fact is in the same memory space
    if (newFact.memorySpaceId !== args.memorySpaceId) {
      throw new ConvexError("FACTS_MUST_BE_IN_SAME_SPACE");
    }

    if (oldFact.factId === newFact.factId || oldFact.supersededBy || newFact.supersededBy
      || (oldFact.validUntil !== undefined && oldFact.validUntil <= Date.now())
      || (newFact.validUntil !== undefined && newFact.validUntil <= Date.now())) dataDenied();
    const now = Date.now();

    await recheckSourceWitnesses(ctx, authority, capability, admittedSources);
    // Mark old fact as superseded
    await ctx.db.patch(oldFact._id, { runtimeEditor: dataEditor(authority),
      supersededBy: args.newFactId,
      validUntil: now,
      updatedAt: now,
    });

    // Update new fact to reference old
    await ctx.db.patch(newFact._id, { runtimeEditor: dataEditor(authority),
      supersedes: args.oldFactId,
      updatedAt: now,
    });

    const witnesses = [...admittedSources, ...await assertDataRow(ctx, authority, capability, oldFact), ...await assertDataRow(ctx, authority, capability, newFact)];
    await recheckSourceWitnesses(ctx, authority, capability, witnesses);
    return {
      superseded: true,
      oldFactId: args.oldFactId,
      newFactId: args.newFactId,
      reason: args.reason,
    };
  },
});

/**
 * Update a fact in place (without creating new version)
 * Used by belief revision for UPDATE action
 */
export const updateInPlace = mutation({
  args: {
    memorySpaceId: v.string(),
    factId: v.string(),
    fact: v.optional(v.string()),
    confidence: v.optional(v.number()),
    tags: v.optional(v.array(v.string())),
    validUntil: v.optional(v.number()),
    metadata: v.optional(v.any()),
    // Enrichment fields
    category: v.optional(v.string()),
    searchAliases: v.optional(v.array(v.string())),
    semanticContext: v.optional(v.string()),
    entities: v.optional(
      v.array(
        v.object({
          name: v.string(),
          type: v.string(),
          fullValue: v.optional(v.string()),
        }),
      ),
    ),
    relations: v.optional(
      v.array(
        v.object({
          subject: v.string(),
          predicate: v.string(),
          object: v.string(),
        }),
      ),
    ),
  },
  handler: async (ctx, args) => {
    const capability = "write" as const;
    const authority = await requireDataAuthority(ctx, args, capability);
    const existing = await getScopedFact(ctx, authority, args.factId, capability);

    if (!existing) {
      throw new ConvexError("FACT_NOT_FOUND");
    }

    // Verify memorySpace owns this fact
    if (existing.memorySpaceId !== args.memorySpaceId) {
      throw new ConvexError("PERMISSION_DENIED");
    }

    if (existing.supersededBy || (existing.validUntil !== undefined && existing.validUntil <= Date.now())) dataDenied();
    const now = Date.now();

    // Build update object with only provided fields
    const updates: Partial<Omit<Doc<"facts">, "_id" | "_creationTime">> = {
      updatedAt: now,
    };

    if (args.fact !== undefined) updates.fact = args.fact;
    if (args.confidence !== undefined) updates.confidence = args.confidence;
    if (args.tags !== undefined) updates.tags = args.tags;
    if (args.validUntil !== undefined) updates.validUntil = args.validUntil;
    if (args.metadata !== undefined) updates.metadata = args.metadata;
    if (args.category !== undefined) updates.category = args.category;
    if (args.searchAliases !== undefined)
      updates.searchAliases = args.searchAliases;
    if (args.semanticContext !== undefined)
      updates.semanticContext = args.semanticContext;
    if (args.entities !== undefined) updates.entities = args.entities;
    if (args.relations !== undefined) updates.relations = args.relations;

    const { lineage, manualSourceBinding } = await reviseDataSource(ctx, authority, existing, args.fact ?? existing.fact);
    await ctx.db.patch(existing._id, { ...updates, runtimeEditor: dataEditor(authority), lineage, manualSourceBinding, sourceType: "manual", extractionPolicyVersion: "manual-assertion-v1", version: existing.version + 1 });

    return await factMutationResult(ctx, authority, existing.factId, existing.ownerPrincipalId!, "updateInPlace");
  },
});

/**
 * Delete many facts matching filters
 */
export const deleteMany = mutation({
  args: {
    memorySpaceId: v.string(),
    userId: v.optional(v.string()),
    factType: v.optional(
      v.union(
        v.literal("preference"),
        v.literal("identity"),
        v.literal("knowledge"),
        v.literal("relationship"),
        v.literal("event"),
        v.literal("observation"),
        v.literal("custom"),
      ),
    ),
  },
  handler: async (ctx, args) => {
    const capability = "write" as const;
    const authority = await requireDataAuthority(ctx, args, capability);
    let facts = await listScopedFacts(ctx, authority, capability);

    // Apply optional filters
    if (args.userId) {
      facts = facts.filter((f) => f.userId === args.userId);
    }
    if (args.factType) {
      facts = facts.filter((f) => f.factType === args.factType);
    }

    const admission = await prepareMutationRowsWrite(ctx, authority, facts);
    const deletions = [];
    let deleted = 0;
    for (const fact of facts) {
      deletions.push(await tombstoneDataRow(ctx, authority, "facts", fact));
      deleted++;
    }

    await finalizeMutationRowsRead(ctx, authority, admission, deletions);
    return { deleted, memorySpaceId: args.memorySpaceId };
  },
});

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// Queries (Read Operations)
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

/**
 * Get fact by ID
 */
export const get = query({
  args: {
    memorySpaceId: v.string(),
    factId: v.string(),
    tenantId: v.optional(v.string()), // Multi-tenancy: SaaS platform isolation
  },
  handler: async (ctx, args) => {
    const capability = "read" as const;
    const authority = await requireDataAuthority(ctx, args, capability);
    const fact = await getScopedFact(ctx, authority, args.factId, capability);

    if (!fact) {
      return null;
    }

    // Verify memorySpace owns this fact
    if (fact.memorySpaceId !== args.memorySpaceId) {
      return null; // Permission denied (silent)
    }

    // Verify tenant isolation if tenantId provided
    if (args.tenantId && fact.tenantId !== args.tenantId) {
      return null; // Cross-tenant access denied (silent)
    }

    return fact;
  },
});

/**
 * List facts with filters
 */
export const list = query({
  args: {
    memorySpaceId: v.string(),
    tenantId: v.optional(v.string()), // Multi-tenancy: SaaS platform isolation
    // Fact-specific filters
    factType: v.optional(
      v.union(
        v.literal("preference"),
        v.literal("identity"),
        v.literal("knowledge"),
        v.literal("relationship"),
        v.literal("event"),
        v.literal("observation"),
        v.literal("custom"),
      ),
    ),
    subject: v.optional(v.string()),
    predicate: v.optional(v.string()),
    object: v.optional(v.string()),
    minConfidence: v.optional(v.number()),
    confidence: v.optional(v.number()), // Exact match
    // Universal filters
    userId: v.optional(v.string()),
    participantId: v.optional(v.string()),
    tags: v.optional(v.array(v.string())),
    tagMatch: v.optional(v.union(v.literal("any"), v.literal("all"))),
    sourceType: v.optional(
      v.union(
        v.literal("conversation"),
        v.literal("system"),
        v.literal("tool"),
        v.literal("manual"),
        v.literal("a2a"),
      ),
    ),
    createdBefore: v.optional(v.number()),
    createdAfter: v.optional(v.number()),
    updatedBefore: v.optional(v.number()),
    updatedAfter: v.optional(v.number()),
    version: v.optional(v.number()),
    includeSuperseded: v.optional(v.boolean()),
    validAt: v.optional(v.number()),
    metadata: v.optional(v.any()),
    limit: v.optional(v.number()),
    offset: v.optional(v.number()),
    sortBy: v.optional(v.string()),
    sortOrder: v.optional(v.union(v.literal("asc"), v.literal("desc"))),
  },
  handler: async (ctx, args) => {
    const capability = "read" as const;
    const authority = await requireDataAuthority(ctx, args, capability);
    let facts = await listScopedFacts(ctx, authority, capability);

    // Filter out superseded by default
    if (!args.includeSuperseded) {
      facts = facts.filter((f) => f.supersededBy === undefined);
    }

    // Tenant isolation filter (apply early for security)
    if (args.tenantId) {
      facts = facts.filter((f) => f.tenantId === args.tenantId);
    }

    // Apply universal filters
    if (args.factType) {
      facts = facts.filter((f) => f.factType === args.factType);
    }
    if (args.subject !== undefined) {
      facts = facts.filter((f) => f.subject === args.subject);
    }
    if (args.predicate !== undefined) {
      facts = facts.filter((f) => f.predicate === args.predicate);
    }
    if (args.object !== undefined) {
      facts = facts.filter((f) => f.object === args.object);
    }
    if (args.userId !== undefined) {
      facts = facts.filter((f) => f.userId === args.userId);
    }
    if (args.participantId !== undefined) {
      facts = facts.filter((f) => f.participantId === args.participantId);
    }
    if (args.minConfidence !== undefined) {
      facts = facts.filter((f) => f.confidence >= args.minConfidence!);
    }
    if (args.confidence !== undefined) {
      facts = facts.filter((f) => f.confidence === args.confidence);
    }
    if (args.sourceType !== undefined) {
      facts = facts.filter((f) => f.sourceType === args.sourceType);
    }
    if (args.tags && args.tags.length > 0) {
      if (args.tagMatch === "all") {
        facts = facts.filter((f) =>
          args.tags!.every((tag) => f.tags.includes(tag)),
        );
      } else {
        // "any" is default
        facts = facts.filter((f) =>
          args.tags!.some((tag) => f.tags.includes(tag)),
        );
      }
    }
    if (args.createdAfter !== undefined) {
      facts = facts.filter((f) => f.createdAt >= args.createdAfter!);
    }
    if (args.createdBefore !== undefined) {
      facts = facts.filter((f) => f.createdAt <= args.createdBefore!);
    }
    if (args.updatedAfter !== undefined) {
      facts = facts.filter((f) => f.updatedAt >= args.updatedAfter!);
    }
    if (args.updatedBefore !== undefined) {
      facts = facts.filter((f) => f.updatedAt <= args.updatedBefore!);
    }
    if (args.version !== undefined) {
      facts = facts.filter((f) => f.version === args.version);
    }
    if (args.validAt !== undefined) {
      facts = facts.filter((f) => {
        const isValid =
          (!f.validFrom || f.validFrom <= args.validAt!) &&
          (!f.validUntil || f.validUntil > args.validAt!);
        return isValid;
      });
    }
    if (args.metadata !== undefined) {
      facts = facts.filter((f) => {
        if (!f.metadata) return false;
        // Match all provided metadata fields
        return Object.entries(args.metadata as Record<string, any>).every(
          ([key, value]) => f.metadata[key] === value,
        );
      });
    }

    // Apply sorting (safe - only if facts exist and sortBy is valid)
    if (args.sortBy && facts.length > 0) {
      // Validate sortBy is a valid field
      const validSortFields = [
        "createdAt",
        "updatedAt",
        "confidence",
        "version",
      ];
      if (validSortFields.includes(args.sortBy)) {
        const sortField = args.sortBy as
          | "createdAt"
          | "updatedAt"
          | "confidence"
          | "version";
        facts.sort((a, b) => {
          const aVal = a[sortField] as any;
          const bVal = b[sortField] as any;
          const comparison = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
          return args.sortOrder === "asc" ? comparison : -comparison;
        });
      }
    }

    // Apply pagination (offset and limit combined)
    const offset = args.offset || 0;
    const limit = args.limit !== undefined ? offset + args.limit : undefined;
    facts =
      limit !== undefined ? facts.slice(offset, limit) : facts.slice(offset);

    return facts;
  },
});

/**
 * Count facts
 */
export const count = query({
